// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        // admissible domain: a positive deposit and a plain EOA owner distinct from c
        amount = bound(amount, 1, type(uint256).max / 2);
        vm.assume(actor.code.length == 0);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        // deploy a fresh C owned by the fuzzed EOA (owner = msg.sender at construction)
        vm.prank(actor);
        c = new SimpleWallet();

        // owner funds c via the payable fallback
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: amount}("");
        vm.assume(ok);

        // owner drains the contract
        vm.prank(actor);
        c.withdrawAll();

        // general rule: after withdrawAll the contract holds exactly 0 wei
        assertTrue(address(c).balance == 0);
    }
}
